export interface BilingualText {
  en: string;
  ru: string;
}

export interface PrefixVerb {
  id: string;
  prefix: string;
  imperfective: string;
  perfective: string;
  meaning: BilingualText;
  note: BilingualText;
  example: BilingualText;
}

export interface VerbFamily {
  id: string;
  base: string;
  meaning: BilingualText;
  entries: PrefixVerb[];
}

// Explicit lexical entries, never generated by attaching prefixes to a stem.
// Empty aspect fields mean that this card does not list a form of that aspect.
function verb(
  prefix: string,
  imperfective: string,
  perfective: string,
  meaningEn: string,
  meaningRu: string,
  noteEn: string,
  noteRu: string,
  exampleRu: string,
  exampleEn: string,
): PrefixVerb {
  return {
    id: perfective || imperfective,
    prefix,
    imperfective,
    perfective,
    meaning: { en: meaningEn, ru: meaningRu },
    note: { en: noteEn, ru: noteRu },
    example: { ru: exampleRu, en: exampleEn },
  };
}

